const returnFromPending = `-- name: ReturnFromPending :one
UPDATE tickets
SET status           = 'called',
    called_at        = now(),
    returned_at      = now(),
    is_priority_call = TRUE
WHERE id       = $1
  AND booth_id = $2
  AND status   = 'pending'
RETURNING id, visitor_id, booth_id, ticket_group_id, match_session_id, sequence_in_booth, status, match_mode, is_priority_call, created_at, called_at, pending_at, returned_at, admitted_at, cancelled_at
`

type ReturnFromPendingParams struct {
	ID      int64
	BoothID int64
}

// Transitions a pending ticket back to called and marks it as a priority call.
// Returns the updated row so the caller knows the visitor returned.
func (q *Queries) ReturnFromPending(ctx context.Context, arg ReturnFromPendingParams) (Ticket, error) {
	row := q.db.QueryRow(ctx, returnFromPending, arg.ID, arg.BoothID)
	var i Ticket
	err := row.Scan(
		&i.ID,
		&i.VisitorID,
		&i.BoothID,
		&i.TicketGroupID,
		&i.MatchSessionID,
		&i.SequenceInBooth,
		&i.Status,
		&i.MatchMode,
		&i.IsPriorityCall,
		&i.CreatedAt,
		&i.CalledAt,
		&i.PendingAt,
		&i.ReturnedAt,
		&i.AdmittedAt,
		&i.CancelledAt,
	)
	return i, err
}

const setTicketPending = `-- name: SetTicketPending :exec
UPDATE tickets
SET status     = 'pending',
    pending_at = now()
WHERE id       = $1
  AND booth_id = $2
  AND status   = 'called'
`

type SetTicketPendingParams struct {
	ID      int64
	BoothID int64
}

// Transitions a called ticket to pending (No-Show after call_resend_minutes).
func (q *Queries) SetTicketPending(ctx context.Context, arg SetTicketPendingParams) error {
	_, err := q.db.Exec(ctx, setTicketPending, arg.ID, arg.BoothID)
	return err
}

const updateTicketGroupID = `-- name: UpdateTicketGroupID :exec
UPDATE tickets
SET ticket_group_id = $2
WHERE id = $1
`

type UpdateTicketGroupIDParams struct {
	ID            int64
	TicketGroupID int64
}

func (q *Queries) UpdateTicketGroupID(ctx context.Context, arg UpdateTicketGroupIDParams) error {
	_, err := q.db.Exec(ctx, updateTicketGroupID, arg.ID, arg.TicketGroupID)
	return err
}

const updateTicketStatus = `-- name: UpdateTicketStatus :exec
UPDATE tickets
SET
    status       = $2,
    called_at    = CASE WHEN $2 = 'called'    THEN now() ELSE called_at    END,
    pending_at   = CASE WHEN $2 = 'pending'   THEN now() ELSE pending_at   END,
    admitted_at  = CASE WHEN $2 = 'admitted'  THEN now() ELSE admitted_at  END,
    cancelled_at = CASE WHEN $2 = 'cancelled' THEN now() ELSE cancelled_at END
WHERE id = $1
`

type UpdateTicketStatusParams struct {
	ID     int64
	Status string
}

func (q *Queries) UpdateTicketStatus(ctx context.Context, arg UpdateTicketStatusParams) error {
	_, err := q.db.Exec(ctx, updateTicketStatus, arg.ID, arg.Status)
	return err
}
